<?php
require_once __DIR__ . '/_layout.php';requirePermission('expenses.manage');
[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$expenses=dbFetchAll("SELECT e.*,a.name agency_name,v.registration_number FROM expenses e JOIN agencies a ON a.id=e.agency_id LEFT JOIN vehicles v ON v.id=e.vehicle_id WHERE e.agency_id IN ($ph) ORDER BY e.expense_date DESC,e.id DESC LIMIT 200",$ids);backofficeHeader(t('page.expenses.title'),'expenses.php');pageHeader('page.expenses.title','page.expenses.description',['breadcrumbs'=>[['label'=>'nav.finance'],['label'=>'nav.expenses']],'primary'=>['label'=>'action.add_expense','href'=>'expense_form.php']]);?>
<div class="grid"><section class="card full"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.expense_register'))?></h2></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.date'))?></th><th><?=e(t('field.agency'))?></th><th><?=e(t('field.description'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('field.method'))?></th><th><?=e(t('common.status'))?></th></tr></thead><tbody><?php foreach($expenses as$expense):?><tr><td><?=formattedDate($expense['expense_date'])?></td><td><?=e($expense['agency_name'])?></td><td><a class="detail-link" href="expense_detail.php?id=<?=e($expense['id'])?>"><?=e($expense['description'])?></a></td><td><?=money($expense['amount'],$expense['currency'])?></td><td><?=e($expense['method']?t('option.'.$expense['method']):t('common.legacy_unspecified'))?></td><td><?=statusBadge($expense['status'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php backofficeFooter();
